from irr_legacy import irr
import math

# search for cases producing rate <= -1, complex, ZeroDivisionError, or huge garbage
found = {"below_minus1": [], "complex": [], "zde": [], "huge": []}
cfs = [
    [1000, -2900, 1950, -500],
    [-1, 2.5, -1.5],
    [-100, 230, -132],
    [-4000, 12000, -12000, 4000],
    [1, -3, 3.3, -1.32],
    [-123400, 36200, 54800, 47800],
    [500, -1200, 800, -150],
]
for cf in cfs:
    for g in (-0.9, -0.5, -2.0, -10.0, 0.0, 0.05, 0.5, 5.0, 50.0, 1e5):
        try:
            r = irr(cf, guess=g)
            if isinstance(r, complex):
                found["complex"].append((cf, g, r))
            elif isinstance(r, float) and (math.isnan(r) or r <= -1):
                found["below_minus1"].append((cf, g, r))
            elif isinstance(r, float) and abs(r) > 1e3:
                found["huge"].append((cf, g, r))
        except ZeroDivisionError:
            found["zde"].append((cf, g))
        except Exception as e:
            print("other:", type(e).__name__, cf[:4], g)

for k, v in found.items():
    print(k, len(v), v[:3])
EOF')

