from irr_legacy import irr
import math, random, itertools

random.seed(7)
hits = []
for trial in range(20000):
    n = random.choice([3, 4])
    cf = [random.choice([-1, 1]) * round(random.uniform(50, 5000), 2) for _ in range(n)]
    if all(c >= 0 for c in cf) or all(c <= 0 for c in cf):
        continue
    g = random.uniform(-5, 5)
    try:
        r = irr(cf, guess=g)
        if isinstance(r, complex):
            hits.append(("complex", cf, g, r))
        elif isinstance(r, float) and (r <= -1 or math.isnan(r)):
            hits.append(("bad", cf, g, r))
    except ZeroDivisionError:
        hits.append(("zde", cf, g, None))
    except Exception:
        pass
    if len(hits) > 8:
        break
for h in hits[:9]:
    print(h)
EOF')

