import math, random
from irr_legacy import irr

def npv(r, cf): return sum(c / (1+r)**t for t, c in enumerate(cf))

random.seed(42)
best = None
for _ in range(200000):
    n = random.choice([3, 4])
    cf = [random.choice([-1, 1]) * round(random.uniform(10, 1000)) for _ in range(n)]
    if not (any(c > 0 for c in cf) and any(c < 0 for c in cf)):
        continue
    g = random.uniform(-0.95, 5)
    try:
        r = irr(cf, guess=g)
    except Exception:
        continue
    if isinstance(r, complex) or not math.isfinite(r) or r <= -1:
        continue
    resid = abs(npv(r, cf)) / max(1.0, max(abs(c) for c in cf))
    # inside domain, finite, yet NPV far from zero == silently unconverged
    if best is None or resid > best[0]:
        best = (resid, cf, g, r)
    if best[0] > 0.05:
        break
print("worst:", best)
EOF')
